import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext, NavigationAgent3D } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const SIGHT_RANGE = 12;
const PATROL_SPEED = 1.5;
const CHASE_SPEED = 3.5;
const FIRE_RANGE = 15;
const FIRE_INTERVAL = 1.2;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  readonly wave: number | undefined;
  health: number;
  alive = true;
  canSee = false;
  #navAgent: NavigationAgent3D | undefined;
  #targetPos: Vector3 | undefined;
  #fireTimer = 0;
  #onFire: (origin: Vector3) => void;
  #sightHandle: ScheduleHandle | undefined;
  #moveDir = new Vector3();

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
      readonly wave?: number;
    } = {},
  ) {
    this.wave = options.wave;
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.85),
    });

    try {
      this.#navAgent = new NavigationAgent3D({
        physics: ctx.physics,
        radius: 0.4,
      });
    } catch {
      // Navigation may not be available if recast plugin isn't installed
    }
  }

  startPatrolAndScan(ctx: GameCtx, playerBodyId: number): void {
    const patrol = (): void => {
      if (!this.alive) return;

      // Check if player is in sight range
      const playerPos = ctx.entities.get("player");
      if (playerPos && "mesh" in playerPos) {
        const playerMesh = playerPos.mesh;
        const dist = this.mesh.position.distanceTo(playerMesh.position);
        if (dist < SIGHT_RANGE) {
          // Check line of sight
          const from = this.mesh.position.clone().add(new Vector3(0, 0.6, 0));
          const to = playerMesh.position.clone().add(new Vector3(0, 0.6, 0));
          const direction = to.clone().sub(from).normalize();
          const distance = from.distanceTo(to);

          const hits = directSpaceState(ctx.physics).intersectRay({
            collisionMask: WORLD_LAYER,
            from,
            normal: direction,
            maxDistance: distance,
          });

          // Only see player if ray doesn't hit world geometry
          this.canSee = hits.length === 0;
          if (this.canSee) {
            this.#targetPos = playerMesh.position.clone();
          }
        } else {
          this.canSee = false;
        }
      }

      this.#sightHandle = ctx.after(ctx.random.range(4, 8) / 60, patrol);
    };
    this.#sightHandle = ctx.after(ctx.random.range(1, 3) / 60, patrol);
  }

  update(dt: number, ctx?: GameCtx): void {
    if (!this.alive) return;

    this.#fireTimer -= dt;

    if (this.canSee && this.#targetPos && ctx) {
      // Chase the player
      this.#moveToward(this.#targetPos, CHASE_SPEED, dt, ctx);

      // Fire at player if in range
      const distToPlayer = this.mesh.position.distanceTo(this.#targetPos);
      if (distToPlayer < FIRE_RANGE && this.#fireTimer <= 0) {
        this.#fireTimer = FIRE_INTERVAL;
        const riflePos = this.mesh.position.clone().add(new Vector3(0.3, 0.6, 0));
        this.#onFire(riflePos);
      }
    } else {
      // Patrol slowly
      if (!this.#targetPos) {
        this.#targetPos = this.#getRandomPatrolPoint();
      }

      const distToPatrol = this.mesh.position.distanceTo(this.#targetPos);
      if (distToPatrol < 1.5) {
        this.#targetPos = this.#getRandomPatrolPoint();
      } else {
        this.#moveToward(this.#targetPos, PATROL_SPEED, dt, ctx);
      }
    }
  }

  #moveToward(target: Vector3, speed: number, dt: number, ctx: GameCtx): void {
    const direction = target.clone().sub(this.mesh.position);
    direction.y = 0;
    direction.normalize();

    this.body.velocity.x = direction.x * speed;
    this.body.velocity.z = direction.z * speed;
    this.body.moveAndSlide(dt);
  }

  #getRandomPatrolPoint(): Vector3 {
    const radius = 6;
    const angle = Math.random() * Math.PI * 2;
    return new Vector3(
      Math.cos(angle) * radius,
      this.mesh.position.y,
      Math.sin(angle) * radius,
    );
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      canSee: this.canSee,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#sightHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

