      enemies.push({ id, value: enemy });
      enemy.startPatrolAndScan(ctx, getPlayer().body.body.id);
      return enemy;
    };

    const removeEntity = (id: string): void => {
      if (ctx.entities.get(id) !== undefined) ctx.entities.remove(id);
    };

