export function createProjectileVisual(materials: ShooterMaterials): Mesh {
  return shadowed(new Mesh(new SphereGeometry(0.12, 4, 3), materials.trim), false);
}

export function createEnemyVisual(materials: ShooterMaterials): Group {
  const group = new Group();
  group.name = "enemy-visual";
  const body = block(0.7, 1.6, 0.7, materials.hostile);
  body.position.y = 0.8;
  group.add(body);
  const head = new Mesh(new SphereGeometry(0.35, 6, 5), materials.hostile);
  head.position.y = 1.55;
  head.castShadow = true;
  group.add(head);

  // Rifle in right hand
  const rifleStock = block(0.08, 0.08, 0.6, materials.shadow);
  rifleStock.position.set(0.35, 0.7, -0.1);
  rifleStock.castShadow = true;
  group.add(rifleStock);

  const rifleBarrel = new Mesh(
    new CylinderGeometry(0.05, 0.05, 0.8, 6).rotateZ(Math.PI / 2),
    materials.shadow,
  );
  rifleBarrel.position.set(0.5, 0.8, -0.2);
  rifleBarrel.castShadow = true;
  group.add(rifleBarrel);

  const rifleGrip = block(0.06, 0.12, 0.1, materials.trim);
  rifleGrip.position.set(0.3, 0.5, -0.15);
  rifleGrip.castShadow = true;
  group.add(rifleGrip);

  return group;
}

